import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第十章 供用电、水、气、热力合同","description":"","frontmatter":{"title":"第十章 供用电、水、气、热力合同","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/dierfenbian：dianxinghetong（dishizhang：gongyongdian、shui、qi、relihetong）.md","filePath":"blogs/CC/第二分编：典型合同（第十章：供用电、水、气、热力合同）.md"}'),o={name:"blogs/CC/dierfenbian：dianxinghetong（dishizhang：gongyongdian、shui、qi、relihetong）.md"};function n(h,a,l,_,d,s){return t(),i("div",null,[...a[0]||(a[0]=[r('<h3 id="第六百四十八条" tabindex="-1">第六百四十八条 <a class="header-anchor" href="#第六百四十八条" aria-label="Permalink to &quot;第六百四十八条&quot;">​</a></h3><p>供用电合同是供电人向用电人供电，用电人支付电费的合同。 向社会公众供电的供电人，不得拒绝用电人合理的订立合同要求。</p><h3 id="第六百四十九条" tabindex="-1">第六百四十九条 <a class="header-anchor" href="#第六百四十九条" aria-label="Permalink to &quot;第六百四十九条&quot;">​</a></h3><p>供用电合同的内容一般包括供电的方式、质量、时间，用电容量、地址、性质，计量方式，电价、电费的结算方式，供用电设施的维护责任等条款。</p><h3 id="第六百五十条" tabindex="-1">第六百五十条 <a class="header-anchor" href="#第六百五十条" aria-label="Permalink to &quot;第六百五十条&quot;">​</a></h3><p>供用电合同的履行地点，按照当事人约定；当事人没有约定或者约定不明确的，供电设施的产权分界处为履行地点。</p><h3 id="第六百五十一条" tabindex="-1">第六百五十一条 <a class="header-anchor" href="#第六百五十一条" aria-label="Permalink to &quot;第六百五十一条&quot;">​</a></h3><p>供电人应当按照国家规定的供电质量标准和约定安全供电。供电人未按照国家规定的供电质量标准和约定安全供电，造成用电人损失的，应当承担赔偿责任。</p><h3 id="第六百五十二条" tabindex="-1">第六百五十二条 <a class="header-anchor" href="#第六百五十二条" aria-label="Permalink to &quot;第六百五十二条&quot;">​</a></h3><p>供电人因供电设施计划检修、临时检修、依法限电或者用电人违法用电等原因，需要中断供电时，应当按照国家有关规定事先通知用电人；未事先通知用电人中断供电，造成用电人损失的，应当承担赔偿责任。</p><h3 id="第六百五十三条" tabindex="-1">第六百五十三条 <a class="header-anchor" href="#第六百五十三条" aria-label="Permalink to &quot;第六百五十三条&quot;">​</a></h3><p>因自然灾害等原因断电，供电人应当按照国家有关规定及时抢修；未及时抢修，造成用电人损失的，应当承担赔偿责任。</p><h3 id="第六百五十四条" tabindex="-1">第六百五十四条 <a class="header-anchor" href="#第六百五十四条" aria-label="Permalink to &quot;第六百五十四条&quot;">​</a></h3><p>用电人应当按照国家有关规定和当事人的约定及时支付电费。用电人逾期不支付电费的，应当按照约定支付违约金。经催告用电人在合理期限内仍不支付电费和违约金的，供电人可以按照国家规定的程序中止供电。 供电人依据前款规定中止供电的，应当事先通知用电人。</p><h3 id="第六百五十五条" tabindex="-1">第六百五十五条 <a class="header-anchor" href="#第六百五十五条" aria-label="Permalink to &quot;第六百五十五条&quot;">​</a></h3><p>用电人应当按照国家有关规定和当事人的约定安全、节约和计划用电。用电人未按照国家有关规定和当事人的约定用电，造成供电人损失的，应当承担赔偿责任。</p><h3 id="第六百五十六条" tabindex="-1">第六百五十六条 <a class="header-anchor" href="#第六百五十六条" aria-label="Permalink to &quot;第六百五十六条&quot;">​</a></h3><p>供用水、供用气、供用热力合同，参照适用供用电合同的有关规定。</p>',18)])])}const u=e(o,[["render",n]]);export{p as __pageData,u as default};
